style:
.modern-grid-container { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px 18px; padding: 20px; max-width: 100%; margin: auto; }
.group-title { grid-column: 1 / -1; display: flex; align-items: center; justify-content: center; gap: 16px; margin: 8px 0 2px; }
.group-title::before, .group-title::after { content: ""; height: 1px; flex: 1; max-width: 340px; border-radius: 999px; background: linear-gradient(90deg, transparent, rgba(31, 78, 121, 0.38)); }
.group-title::after { background: linear-gradient(90deg, rgba(31, 78, 121, 0.38), transparent); }
.group-title span { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-width: 96px; padding: 6px 16px; border-radius: 999px; background: rgba(31, 78, 121, 0.055); border: 1px solid rgba(31, 78, 121, 0.18); color: #1f4e79; font-size: 12px; font-weight: 800; letter-spacing: 0.25px; line-height: 1; white-space: nowrap; }
.group-title span::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: #1f4e79; box-shadow: 0 0 0 3px rgba(31, 78, 121, 0.08); flex: 0 0 auto; }
.modern-card { display: flex; flex-direction: column; align-items: center; justify-content: center; background: #ffffff; border: 1px solid #eef1f4; border-radius: 18px; padding: 24px 14px; text-decoration: none !important; transition: all 0.22s ease; box-shadow: 0 4px 12px rgba(15, 23, 42, 0.035); min-height: 136px; overflow: hidden; }
.modern-card:hover { transform: translateY(-3px); box-shadow: 0 10px 22px rgba(15, 23, 42, 0.06); border-color: #e2e8f0; }
.icon-wrapper { width: 54px; height: 54px; border-radius: 16px; display: flex; align-items: center; justify-content: center; margin-bottom: 14px; flex-shrink: 0; transition: transform 0.22s ease; }
.modern-card:hover .icon-wrapper { transform: scale(1.04); }
.icon-wrapper svg { width: 26px; height: 26px; }
.modern-card span { font-size: 13px; font-weight: 700; color: #334155; text-align: center; line-height: 1.45; display: block; overflow: hidden; width: 100%; }
.bg-purple { background-color: #faf5ff; color: #9333ea; }
.bg-orange { background-color: #fff7ed; color: #ea580c; }
.bg-blue { background-color: #eff6ff; color: #2563eb; }
.bg-green { background-color: #f0fdf4; color: #16a34a; }
[dir="rtl"] .modern-grid-container { direction: rtl; }
@media (max-width: 1024px) { .modern-grid-container { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 768px) { .modern-grid-container { grid-template-columns: repeat(2, 1fr); gap: 12px 14px; padding: 16px; }
  .group-title span { font-size: 11px; min-width: 82px; padding: 6px 12px; }
  .modern-card { min-height: 122px; padding: 18px 10px; } .icon-wrapper { width: 48px; height: 48px; border-radius: 14px; margin-bottom: 11px; } .modern-card span { font-size: 12px; } }
@media (max-width: 480px) { .modern-grid-container { grid-template-columns: 1fr; } }

